let REAL = {};
let realLoaded = false;

function detectKey(el) {
  let key = null;
  el.classList.forEach((c) => { if (c.startsWith('bg-')) key = c.slice(3); });
  if (!key) {
    const t = (el.parentElement?.textContent || '').toLowerCase();
    if (t.includes('disney')) key = 'disney';
    else if (t.includes('hbo') || t.includes('max')) key = 'max';
    else if (t.includes('netflix')) key = 'netflix';
    else if (t.includes('prime') || t.includes('amazon')) key = 'amazon';
    else if (t.includes('apple')) key = 'apple';
    else if (t.includes('paramount')) key = 'paramount';
    else if (t.includes('hulu')) key = 'hulu';
    else if (t.includes('peacock')) key = 'peacock';
    else if (t.includes('crunchyroll')) key = 'crunchyroll';
  }
  return key;
}

function applySvg(el, logo) {
  if (!logo) return;
  el.style.background = logo.bg || 'transparent';
  el.style.display = 'inline-flex';
  el.style.alignItems = 'center';
  el.style.justifyContent = 'center';
  el.style.overflow = 'hidden';
  el.style.borderRadius = '8px';
  el.style.padding = '0';
  el.style.boxShadow = '0 3px 10px rgba(0,0,0,.5)';
  el.innerHTML = logo.svg;
}

function upgrade(el) {
  if (el.dataset.brandDone) return;
  const key = detectKey(el);
  if (!key || !SVG_LOGOS[key]) return;
  el.dataset.brandDone = '1';
  applySvg(el, SVG_LOGOS[key]);
}

function scan(root = document) {
  root.querySelectorAll('.brand-badge').forEach(upgrade);
}

// Generates the mini, minimal high-quality official streaming pill for detail modal
export function renderStreamPill(stream) {
  if (!stream || (!stream.key && !stream.name && !stream.logo)) return null;
  let key = stream.key || '';
  if (key === 'hbo') key = 'max';
  const name = stream.name || 'Streaming';
  const pill = document.createElement('span');
  pill.className = 'own-pill stream-pill' + (key ? ' stream-' + key : '');
  pill.title = name;
  pill.setAttribute('aria-label', name);

  if (MINI_SVGS[key]) {
    pill.innerHTML = MINI_SVGS[key];
  } else if (stream.logo) {
    const img = document.createElement('img');
    img.src = stream.logo;
    img.alt = name;
    img.loading = 'lazy';
    img.referrerPolicy = 'no-referrer';
    img.onerror = () => {
      pill.innerHTML = `<span class="stream-text">${name}</span>`;
    };
    pill.appendChild(img);
  } else {
    pill.innerHTML = `<span class="stream-text">${name}</span>`;
  }
  return pill;
}

window.renderStreamPill = renderStreamPill;
window.SVG_LOGOS = SVG_LOGOS;
window.MINI_SVGS = MINI_SVGS;

scan();

const obs = new MutationObserver((muts) => {
  for (const m of muts) {
    for (const n of m.addedNodes) {
      if (n.nodeType !== 1) continue;
      if (n.classList && n.classList.contains('brand-badge')) upgrade(n);
      if (n.querySelectorAll) n.querySelectorAll('.brand-badge').forEach(upgrade);
    }
  }
});
obs.observe(document.body, { childList: true, subtree: true });
